// ============================================
// 📊 STEP 1: Analyze Content for Citations
// ============================================

const inputData = $input.first().json;

// Handle different input formats
let content = '';
let title = '';

// Try to extract content from various formats
if (inputData['choices[0].message.content']) {
  // From Split Out node
  content = inputData['choices[0].message.content'];
} else if (inputData.content) {
  content = inputData.content;
} else if (inputData.body && inputData.body.content) {
  // From Webhook body
  content = inputData.body.content;
} else if (inputData.choices && inputData.choices[0]) {
  content = inputData.choices[0].message.content;
}

// Extract title
title = inputData.title || inputData.originalTitle || (inputData.body && inputData.body.title) || '';

if (!content) {
  throw new Error('❌ No content provided');
}

// Extract main topics from H2/H3 headers
const headers = [...content.matchAll(/##\s+(.+)/g)].map(m => m[1].trim());

// Identify 7 citation opportunities
const opportunities = [];

// Strategy: Find claims that need scientific backing
const claimPatterns = [
  /تحقیقات نشان می‌دهد/g,
  /مطالعات علمی/g,
  /پژوهش‌ها/g,
  /آمار/g,
  /درصد/g,
  /خواص درمانی/g,
  /ضد باکتری/g,
  /ضد التهاب/g,
  /تقویت سیستم ایمنی/g
];

let opportunityCount = 0;

// Find sentences with claims
const sentences = content.split(/[.!?]/).filter(s => s.length > 30);

for (const sentence of sentences) {
  if (opportunityCount >= 7) break;

  for (const pattern of claimPatterns) {
    if (pattern.test(sentence)) {
      // Remove the claim phrase to focus on the subject
      const coreContent = sentence.replace(pattern, '').trim();

      // Extract relevant keywords
      const keywords = coreContent
        .replace(/[^\u0600-\u06FF\s]/g, '')
        .split(/\s+/)
        .filter(w => w.length > 3)
        .slice(0, 7)
        .join(' ');

      const section = headers[Math.floor(opportunityCount / 2)] || 'General';

      // Combine section and keywords for better relevance
      const finalKeywords = section !== 'General' ? `${section} ${keywords}` : keywords;

      opportunities.push({
        index: opportunityCount,
        claim: sentence.trim(),
        keywords_fa: finalKeywords,
        keywords_en: '', // Will be translated
        section: section
      });

      opportunityCount++;
      break;
    }
  }
}

// If not enough, add generic opportunities based on headers
while (opportunities.length < 7 && headers.length > 0) {
  const header = headers[opportunities.length % headers.length];
  opportunities.push({
    index: opportunities.length,
    claim: header,
    keywords_fa: header,
    keywords_en: '',
    section: header
  });
}

return {
  json: {
    opportunities: opportunities,
    totalFound: opportunities.length,
    originalContent: content,
    originalTitle: title
  }
};

// ============================================
// 🌐 STEP 2: Translate Keywords to English
// ============================================

const opportunities = $input.first().json.opportunities || [];

// Persian to English keyword mapping for honey topics
const translationMap = {
  'عسل': 'honey',
  'خواص': 'properties benefits',
  'درمانی': 'therapeutic medicinal',
  'ضد باکتری': 'antibacterial antimicrobial',
  'ضد التهاب': 'anti-inflammatory',
  'سیستم ایمنی': 'immune system',
  'تقویت': 'boost strengthen',
  'سلامت': 'health',
  'پوست': 'skin',
  'زخم': 'wound healing',
  'سرماخوردگی': 'cold flu',
  'گلو': 'throat',
  'سرفه': 'cough',
  'آنتی اکسیدان': 'antioxidant',
  'ویتامین': 'vitamin',
  'مواد مغذی': 'nutrients',
  'قند': 'sugar glucose',
  'طبیعی': 'natural raw',
  'ارگانیک': 'organic',
  'خالص': 'pure'
};

const translatedOpportunities = opportunities.map(opp => {
  let englishKeywords = [];

  // Translate each Persian word
  const words = opp.keywords_fa.split(/\s+/);

  for (const word of words) {
    const translation = translationMap[word];
    if (translation) {
      englishKeywords.push(translation);
    }
  }

  // Default if no translation found
  if (englishKeywords.length === 0) {
    englishKeywords = ['honey', 'health', 'benefits'];
  }

  return {
    ...opp,
    keywords_en: englishKeywords.join(' ')
  };
});

return {
  json: {
    opportunities: translatedOpportunities,
    readyForSearch: true
  }
};

// ============================================
// 📊 STEP 3: Prepare Search Queries (Dynamic & Targeted)
// ============================================

const items = $input.all();
const results = [];

// Helper to process a single opportunity
function processOpportunity(opp) {
  const keywords = opp.keywords_fa || opp.keywords_en || '';

  // 🎯 Dynamic Search Strategy:
  // Use site:.ir to capture all Iranian domains (including .gov.ir, .ac.ir)
  // This is broader and more likely to return results than a complex OR query
  const query = `${keywords} site:.ir`;

  return {
    json: {
      ...opp,
      searchQuery: query,
      targetDomain: 'iranian_national',
      searchType: 'dynamic_opportunity'
    }
  };
}

for (const item of items) {
  const data = item.json;

  if (data.opportunities && Array.isArray(data.opportunities)) {
    // Case 1: Array of opportunities in one item
    for (const opp of data.opportunities) {
      results.push(processOpportunity(opp));
    }
  } else if (data.claim || data.keywords_fa) {
    // Case 2: Single opportunity item
    results.push(processOpportunity(data));
  }
}

return results;

// Get all AI responses (input items)
const aiResponses = $input.all();
// Get all original items from the Split node
const allItems = $('Split for Anchor').all();
const results = [];

// Loop through each AI response
for (let i = 0; i < aiResponses.length; i++) {
  const aiResponse = aiResponses[i].json;
  let anchorText = '';

  // Extract anchor text from AI response
  if (aiResponse.choices && aiResponse.choices[0]) {
    anchorText = aiResponse.choices[0].message.content.trim();
  }

  // Get the corresponding original link data using the index
  // This works because the order of execution is preserved
  const originalLink = allItems[i]?.json || {link: '', title: 'مطالعه علمی', domain: '', index: 0, snippet: '', claim: '', section: ''};

  // Fallback if anchor is empty or too short
  if (!anchorText || anchorText.length < 5) {
    anchorText = originalLink.title?.substring(0, 50) || 'مطالعه علمی';
  }

  // Push the combined result
  results.push({
    json: {
      url: originalLink.link,
      anchor: anchorText,
      domain: originalLink.domain,
      index: originalLink.index,
      title: originalLink.title,
      snippet: originalLink.snippet,
      claim: originalLink.claim,
      section: originalLink.section
    }
  });
}

return results;

// ============================================
// 📝 STEP 11: Prepare Final Links
// ============================================

const items = $input.all();

const finalLinks = items.map((item, idx) => {
  const data = item.json;

  return {
    index: idx,
    url: data.url,
    anchor: data.anchor,
    domain: data.domain,
    section: data.section,
    claim: data.claim
  };
});

return {
  json: {
    links: finalLinks,
    totalLinks: finalLinks.length,
    readyForInsertion: true
  }
};

// ============================================
// 📊 STEP 9: Collect Valid Links
// ============================================

const items = $input.all();
const validLinks = [];

for (const item of items) {
  const data = item.json;

  if (data.foundLink && data.foundTitle) {
    validLinks.push({
      title: data.foundTitle,
      link: data.foundLink,
      snippet: data.foundSnippet,
      originalClaim: data.claim,
      keywords: data.keywords_fa,
      section: data.section,
      sourceType: data.sourceType,
      domainScore: data.domainScore
    });
  }
}

return {
  json: {
    validLinks: validLinks,
    count: validLinks.length
  }
};

// ============================================
// 📊 STEP 5: Extract Best URL (Smart Filtering)
// ============================================

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const organic = data.organic || [];

  let bestResult = null;
  let bestScore = -1;

  // 🧠 Scoring Algorithm to find the "Best" Backlink Opportunity
  for (const result of organic) {
    let score = 0;
    const link = result.link || '';
    const title = result.title || '';

    // 1. Domain Authority Priority
    if (link.includes('.gov.ir')) score += 20;
    else if (link.includes('.ac.ir')) score += 15;
    else if (link.includes('.ir')) score += 10;

    // 2. Relevance (Simple keyword check in title)
    // Assuming keywords are in data.keywords_fa
    if (data.keywords_fa) {
        const keywords = data.keywords_fa.split(' ');
        let matchCount = 0;
        for(const word of keywords) {
            if (word.length > 2 && title.includes(word)) matchCount++;
        }
        score += matchCount * 2;
    }

    // 3. Penalize PDF/Doc files (usually not good for linking directly in text)
    if (link.endsWith('.pdf') || link.endsWith('.doc')) score -= 5;

    // Select the winner
    if (score > bestScore) {
      bestScore = score;
      bestResult = result;
    }
  }

  if (bestResult) {
    results.push({
      json: {
        ...data, // Keep original metadata
        foundTitle: bestResult.title,
        foundLink: bestResult.link,
        foundSnippet: bestResult.snippet,
        domainScore: bestScore,
        sourceType: bestResult.link.includes('.gov.ir') ? 'Government' : (bestResult.link.includes('.ac.ir') ? 'Academic' : 'National')
      }
    });
  } else {
    // Fallback: If no results found, we might want to log it or skip
    // For now, we skip to ensure only valid links are returned
  }
}

return results;

// ============================================
// Split validLinks array into individual items
// ============================================

const data = $input.first().json;
const validLinks = data.validLinks || [];

if (validLinks.length === 0) {
  throw new Error('❌ No valid links to process');
}

console.log(`📤 Splitting ${validLinks.length} links for anchor generation`);

return validLinks.map(link => ({
  json: link
}));

// گرفتن همه آیتم‌ها
const items = $input.all();

// ساخت آرایه‌ای از همه عناوین
const titles = items.map(item => item.json.title);

// انتخاب یک عنوانِ تصادفی
const randomIndex = Math.floor(Math.random() * titles.length);
const chosenTitle = titles[randomIndex];

// بازگرداندن فقط یک آیتم
return [
  {
    json: {
      title: chosenTitle
    }
  }
];
